		keyName = "speedFormat",
		name = "Weapon speed units",
		description = "Show weapon speed in seconds, as the game does, or in game ticks",
		position = 4,
		section = displaySection
	)
	default SpeedFormat speedFormat()
	{
		return SpeedFormat.SECONDS;
